html:
{% set dob = frappe.db.get_value("Patient", doc.patient, "dob") %}
{% set years = 0 %}
{% set months = 0 %}
{% set days = 0 %}
{% if dob %}
    {% set now  = frappe.utils.nowdate() %}
    {% set diff = frappe.utils.date_diff(now, dob) %}
    {% set years = diff//365 %}
    {% set months = (diff - (years * 365))//30 %}
    {% set days = ( (diff - (years * 365)) - (months * 30) ) %}
{% endif %}
{% set age_display = "" %}
{% if years > 0 %}
    {% set age_display = years|str + 'Y' %}
{% else %}
    {% set age_display = months|str + 'M ' + days|str + 'D'  %}
{% endif %}
<div style="font-family: arial, sans-serif;">
    <b><div style="text-align: center; margin-bottom: -2px; font-size:8px;">{{doc.patient_name|upper}}<br>
    {{doc.patient}}, {{age_display}} / {{doc.patient_gender[:1]}}</div>
    <div style="text-align:center;"><img class="barcode" style="width: 350px; height: 50px;" src="data:image/png;base64,{{ generate_barcodes(doc.name) }}"></div>
    <div  style="text-align:center; font-size:8px; margin-top: -8px;">{{doc.name}}</div>
    <div style="text-align: center; font-size:8px;">{{doc.specimen_type|upper}}</div></b>
</div>

{#- Jeevan Healthcare Bill of Supply - A5 landscape, compact, boxed layout. Paste into Print Format > HTML.
    The logo comes from the Letter Head (selected one, else the default Letter Head image). -#}
{%- set shop = {
  "title": "BILL OF SUPPLY",
  "proprietor": "NARESH KUMAR",
  "remarks": ["Thank you. Visit again", "Must bring the Bill for returns"],
  "qr": "",
  "sign": ""
} -%}
{#- min_rows: total item rows (filled + blank). Rows are a fixed 4.3mm tall, so this pushes REMARKS/TOTALS to the page bottom.
    If the bill spills to a 2nd page lower it by 1-2; if there is a gap above REMARKS raise it. -#}
{%- set min_rows = 18 -%}
{%- set lh_img = "" -%}
{%- if not letter_head -%}
  {%- set lh_img = frappe.db.get_value("Letter Head", {"is_default": 1}, "image") or "" -%}
{%- endif -%}
{%- set co = frappe.db.get_value("Company", doc.company, ["phone_no", "email"], as_dict=True) or {} -%}
{%- set addr_rec = frappe.db.get_all("Address", filters=[["Dynamic Link", "link_doctype", "=", "Company"], ["Dynamic Link", "link_name", "=", doc.company]], fields=["address_line1", "address_line2", "city", "state", "pincode"], limit=1) -%}
{%- set a = addr_rec[0] if addr_rec else {} -%}
{%- set co_addr = ([a.address_line1, a.address_line2, a.city, a.state, a.pincode]|select|join(", ")) if a else ((doc.company_address_display or "")|striptags|replace("\n", ", ")|replace("Phone:", "|")|replace("Email:", "|")|replace("\r", "")).split("|")[0] -%}
{%- set ns = namespace(units_total=0, qty=0, gross=0, net=0) -%}
<meta name="pdfkit-page-size" content="A5">
<meta name="pdfkit-orientation" content="Landscape">
<meta name="pdfkit-margin-top" content="4mm">
<meta name="pdfkit-margin-bottom" content="4mm">
<meta name="pdfkit-margin-left" content="4mm">
<meta name="pdfkit-margin-right" content="4mm">
<style>
  @page { size: 210mm 148mm; margin: 4mm; }
  @media print { @page { size: A5 landscape; margin: 4mm; } }
  .jh { font-family: Arial, Helvetica, sans-serif; font-size: 6.5pt; color: #000; }
  .jh table, .jh tr, .jh td, .jh th, .jh div, .jh p { line-height: 1.1 !important; }
  .jh table { width: 100%; border-collapse: collapse; margin: 0 !important; }
  .jh td, .jh th { padding: 0 3px !important; vertical-align: top; border: 0; }
  .jh .sheet { border: 0.9pt solid #000; }
  .jh .box.nt { border-top: 0.9pt solid #000; }

  /* header */
  .jh .head > tbody > tr > td { padding: 0 !important; }
  .jh .c-left { width: 17%; border-right: 0.9pt solid #000; text-align: center; }
  .jh .c-left .title { font-size: 7.5pt; font-weight: bold; padding: 2px 0 !important; border-bottom: 0.9pt solid #000; }
  .jh .c-left .logo { padding: 3px 2px !important; }
  .jh .c-left .letter-head, .jh .c-left .letter-head * { margin: 0 !important; padding: 0 !important; }
  .jh .c-left img { max-height: 13mm; max-width: 100%; width: auto; height: auto; }
  .jh .head > tbody > tr > td.c-shop { width: 47%; border-right: 0.9pt solid #000; padding: 2px 6px !important; }
  .jh .shop-name { font-size: 12pt; font-weight: 900; line-height: 1.1 !important; margin: 0 0 2px; }
  .jh .c-inv { width: 36%; }
  .jh .inv-line { border-bottom: 0.9pt solid #000; }
  .jh .inv-line td { padding: 2px 5px !important; font-size: 9pt; font-weight: bold; }
  .jh .inv-line td.dt { text-align: right; font-size: 7.5pt; }
  .jh .kv td { font-size: 6pt; padding: 0.4px 5px 0.4px 0 !important; }
  .jh .c-inv .kv { margin: 2px 5px !important; width: auto; }
  .jh .kv .k { white-space: nowrap; width: 1%; padding-right: 8px !important; }

  /* items: vertical lines run full height */
  .jh .items th { border: 0.6pt solid #000; border-top: 0; font-weight: bold; text-align: left; font-size: 6.5pt; height: 5.6mm; padding: 1.5px 4px !important; vertical-align: middle !important; }
  .jh .items td { border-left: 0.6pt solid #000; border-right: 0.6pt solid #000; font-size: 7.5pt; height: 4.3mm; padding: 0 4px !important; vertical-align: middle !important; }
  .jh .items tr.blank td { height: 4.3mm; }
  .jh .items tr.gap td { height: 1.6mm; padding: 0 !important; }
  .jh .items th:first-child, .jh .items td:first-child { border-left: 0; }
  .jh .items th:last-child, .jh .items td:last-child { border-right: 0; }
  .jh .items tr:last-child td { border-bottom: 0; }
  .jh .c { text-align: center !important; }
  .jh .n { text-align: right !important; }
  .jh .sn { text-align: center; }

  /* footer */
  .jh .foot td { font-size: 6.8pt; height: 5.2mm; padding: 1.5px 5px !important; vertical-align: middle !important; }
  .jh .foot .rem { border-right: 0.6pt solid #000; vertical-align: top !important; padding-top: 2mm !important; }
  .jh .foot .rem .rh td { padding: 0 !important; font-weight: bold; }
  .jh .foot .rem .rh td.e { text-align: right; }
  .jh .foot .mid { border-right: 0.6pt solid #000; text-align: center; padding: 0 !important; }
  .jh .foot .mid img { max-width: 100%; max-height: 14mm; }
  .jh .foot .mid.sg { vertical-align: bottom !important; font-size: 6pt; padding: 0 0 2mm !important; }
  .jh .foot .lab { border-right: 0.6pt solid #000; }
  .jh .foot .val { text-align: right; }
  .jh .foot tr.pay td { border-top: 0.6pt solid #000; border-bottom: 0.6pt solid #000; background: #eee; font-size: 8pt; font-weight: bold; height: 6.4mm; padding: 2px 5px !important; }
  .jh .foot tr.pay td.val { border-right: 0; }
  .jh .prod { margin-top: 3px; }
  .jh .strip td { background: #eee; font-size: 6pt; padding: 1px 5px !important; }
  .jh .strip .r { text-align: right; }
</style>
<div class="jh"><div class="sheet">

<table class="box head"><tr>
  <td class="c-left">
    <div class="title">{{ shop.title }}</div>
    <div class="logo">
    {%- if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>
    {%- elif lh_img %}<img src="{{ lh_img }}" alt="">{% endif %}
    </div>
  </td>
  <td class="c-shop">
    <div class="shop-name">{{ doc.company|upper }}</div>
    <table class="kv">
      <tr><td class="k">PROPRIETOR</td><td><b>{{ shop.proprietor }}</b></td></tr>
      <tr><td colspan="2">{{ co_addr }}</td></tr>
      <tr><td class="k">CONTACT</td><td><b>{{ co.phone_no or "-" }}</b></td></tr>
      <tr><td class="k">EMAIL ID</td><td><b>{{ (co.email or "-")|upper }}</b></td></tr>
    </table>
  </td>
  <td class="c-inv">
    <table class="inv-line"><tr>
      <td>Invoice/{{ doc.name }}</td>
      <td class="dt">{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</td>
    </tr></table>
    <table class="kv">
      <tr><td class="k">PARTY</td><td><b>{{ (doc.customer_name or doc.customer)|upper }}</b></td></tr>
      <tr><td class="k">ADDRESS</td><td>{{ (doc.address_display or "-")|striptags|replace("\n", ", ") }}</td></tr>
      <tr><td class="k">CONTACT</td><td>{{ doc.contact_mobile or "-" }}</td></tr>
    </table>
  </td>
</tr></table>

<table class="box nt items">
  <colgroup>
    <col style="width:4%"><col style="width:25%"><col style="width:7%"><col style="width:15%">
    <col style="width:7%"><col style="width:9%"><col style="width:10%"><col style="width:9%"><col style="width:6%"><col style="width:8%">
  </colgroup>
  <thead><tr>
    <th></th><th>DESCRIPTION</th><th>PACK</th><th>BATCH</th><th class="c">EXP</th>
    <th class="c">QTY</th><th class="n">MRP</th><th class="n">RATE</th><th class="n">DIS %</th><th class="n">AMT</th>
  </tr></thead>
  <tbody>
    <tr class="gap"><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
  {%- for row in doc.items %}
    {%- set b = frappe.db.get_value("Batch", row.batch_no, ["expiry_date", "units_per_pack", "mrp"], as_dict=True) if row.batch_no else None -%}
    {%- set upp = (b.units_per_pack if b and b.units_per_pack else 1) -%}
    {%- set qty = row.qty / upp -%}
    {%- set mrp = (b.mrp if b and b.mrp else row.price_list_rate * upp) -%}
    {%- set rate = row.rate * upp -%}
    {%- set dis = ((1 - rate / mrp) * 100) if mrp else 0 -%}
    {%- set packs = (row.qty // upp)|int -%}
    {%- set units = (row.qty - packs * upp)|round(2) -%}
    {%- set qty_txt = ((packs|string ~ "P") if packs else "") ~ (" " if packs and units else "") ~ (("%g"|format(units) ~ "U") if units else "") -%}
    {%- set qty_txt = qty_txt or "0" -%}
    {%- set ns.qty = ns.qty + qty -%}
    {%- set ns.units_total = ns.units_total + row.qty -%}
    {%- set ns.gross = ns.gross + mrp * qty -%}
    {%- set ns.net = ns.net + row.amount %}
    <tr>
      <td class="sn">{{ loop.index }}</td>
      <td>{{ row.item_name|upper|truncate(34, True, "…") }}</td>
      <td>{{ upp|int }}'S</td>
      <td>{{ row.batch_no or "" }}</td>
      <td class="c">{% if b and b.expiry_date %}{{ frappe.utils.formatdate(b.expiry_date, "MM/yy") }}{% endif %}</td>
      <td class="c">{{ qty_txt }}</td>
      <td class="n">{{ "%.2f"|format(mrp) }}</td>
      <td class="n">{{ "%.2f"|format(rate) }}</td>
      <td class="n">{{ "%.2f"|format(dis) }}</td>
      <td class="n">{{ "%.2f"|format(row.amount) }}</td>
    </tr>
  {%- endfor %}
  {%- set pad = min_rows - (doc.items|length) %}
  {%- if pad > 0 %}{% for i in range(pad) %}
    <tr class="blank"><td class="sn">&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
  {%- endfor %}{% endif %}
  </tbody>
</table>

{%- set to_pay = doc.rounded_total or doc.grand_total -%}
{%- set savings = [ns.gross - ns.net, 0]|max %}
<table class="box nt foot" style="table-layout:fixed">
<colgroup><col style="width:45%"><col style="width:15%"><col style="width:22%"><col style="width:18%"></colgroup>
<tr>
  <td class="rem" rowspan="4">
    <table class="rh"><tr class="rh"><td>REMARKS</td><td class="e">E&amp;OE</td></tr></table>
    {%- for line in shop.remarks %}<div>{{ line }}</div>{% endfor %}
    <div class="prod">PRODUCTS: <b>{{ doc.items|length }}</b>, TOTAL QTY: <b>{{ "%g"|format(ns.units_total|round(2)) }}U</b></div>
  </td>
  <td class="mid sg" rowspan="4">{% if shop.qr %}<img src="{{ shop.qr }}" alt=""><br>{% endif %}{% if shop.sign %}<img src="{{ shop.sign }}" alt=""><br>{% endif %}AUTH SIGN</td>
  <td class="lab">SUBTOTAL</td><td class="val">{{ "%.2f"|format(ns.gross) }}</td>
</tr>
<tr><td class="lab">SAVINGS</td><td class="val">{{ "%.2f"|format(savings) }}</td></tr>
<tr class="pay">
  <td class="lab">TO PAY</td><td class="val">Rs {{ "%.2f"|format(to_pay) }}</td>
</tr>
<tr><td class="lab">PAID/DUE</td><td class="val">{{ "%.2f"|format(to_pay - doc.outstanding_amount) }}/{{ "%.2f"|format(doc.outstanding_amount) }}</td></tr>
</table>

{%- set cs = (doc.creation or "")|string -%}
{%- set hh = cs[11:13]|int -%}
{%- set mon = ["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"][((cs[5:7]|int) - 1) % 12] -%}
{%- set made_by = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner or "" -%}
<table class="box nt strip"><tr>
  <td>ORIGINAL / DUPLICATE / TRIPLICATE</td>
  <td class="r">MADE BY <b>{{ made_by|upper }}</b>{% if cs %} at {{ cs[8:10] }}/{{ mon }} {{ "%02d"|format(hh % 12 or 12) }}:{{ cs[14:16] }} {{ "AM" if hh < 12 else "PM" }}{% endif %}</td>
</tr></table>
</div></div>

{# Patient Encounter - Prescription style. Paste into Print Format (Custom HTML / Jinja) #}
{%- set pt = frappe.db.get_value("Patient", doc.patient, ["patient_name", "mobile", "dob", "sex"], as_dict=True) or {} -%}
{%- set vs = frappe.get_all("Vital Signs", filters={"patient": doc.patient, "docstatus": ["<", 2]},
    fields=["weight", "height", "bmi", "bp_systolic", "bp_diastolic"], order_by="creation desc", limit=1) -%}
{%- set v = vs[0] if vs else {} -%}
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "phone_no", "email"], as_dict=True) or {} -%}
{%- set hpdoc = frappe.get_doc("Healthcare Practitioner", doc.practitioner) if doc.practitioner else None -%}
{%- set reg_no = (hpdoc.get("registration_no") or hpdoc.get("custom_registration_no") or hpdoc.get("custom_reg_no") or "") if hpdoc else "" -%}
{%- set qualif = (hpdoc.get("qualification") or hpdoc.get("custom_qualification") or "") if hpdoc else "" -%}
{%- set pname = doc.patient_name or pt.patient_name or "" -%}
{%- set age = doc.patient_age or (((frappe.utils.date_diff(frappe.utils.nowdate(), pt.dob) // 365) ~ " Y") if pt.dob else "") -%}
{%- set dr = (doc.practitioner_name or doc.practitioner or "") | replace("Dr. ", "") | replace("Dr.", "") | trim -%}
{%- set links = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, fields=["parent"], limit=1) -%}
{%- set addr = frappe.get_doc("Address", links[0].parent) if links else None -%}

<style>
  @page { size: A4 portrait; margin: 10mm; }
  .rx { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #000; position: relative; min-height: 265mm; }
  .rx .bottom { position: absolute; bottom: 0; left: 0; right: 0; }
  .rx table { width: 100%; border-collapse: collapse; }
  .rx td, .rx th { vertical-align: top; padding: 3px 4px; text-align: left; }
  .rx .hdr td { border: none; }
  .rx .hosp { color: #1a1aff; font-size: 16px; font-weight: bold; }
  .rx hr { border: 0; border-top: 1px solid #000; margin: 8px 0; }
  .rx .box th { border-top: 1px solid #000; border-bottom: 1px solid #000; }
  .rx .meds th { border-top: 1px solid #000; border-bottom: 1px solid #000; }
  .rx .meds td { border-bottom: 1px solid #000; padding: 6px 4px; }
  .rx .sub { font-size: 10px; text-transform: uppercase; display: block; margin-top: 4px; }
  .rx .sec { font-weight: bold; margin-top: 12px; }
  .rx ul { margin: 2px 0 0 0; padding-left: 14px; list-style: none; }
  .rx ul li:before { content: "* "; }
  .rx .foot { text-align: center; font-size: 10px; margin-top: 14px; border-top: 1px solid #000; padding-top: 4px; }
</style>

<div class="rx">

  <!-- Header -->
  <table class="hdr">
    <tr>
      <td style="width:40%">
        <b style="font-size:14px">Dr. {{ dr }}</b><br>
        {% if qualif %}{{ qualif }}<br>{% endif %}
        {{ doc.medical_department or "" }}<br>
        {% if reg_no %}Reg. No: {{ reg_no }}{% endif %}
      </td>
      <td style="width:20%; text-align:center">
        <img src="/files/1000007633.png" style="max-height:70px; max-width:100%;">
      </td>
      <td style="width:40%">
        <span class="hosp">{{ co.company_name or doc.company }}</span><br>
        {% if addr %}
          {{ addr.address_line1 or "" }}{% if addr.address_line2 %}, {{ addr.address_line2 }}{% endif %}{% if addr.city %}, {{ addr.city }}{% endif %}{% if addr.state %}, {{ addr.state }}{% endif %}{% if addr.pincode %} - {{ addr.pincode }}{% endif %}<br>
        {% endif %}
        {% if co.phone_no %}Ph: {{ co.phone_no }}<br>{% endif %}
        {% if co.email %}{{ co.email }}{% endif %}
      </td>
    </tr>
  </table>
  <hr>

  <div style="text-align:right"><b>Date: {{ frappe.utils.formatdate(doc.encounter_date, "dd-MMM-yyyy") }}</b></div>

  <!-- Patient -->
  <div style="margin-top:4px">
    <b>ID: {{ doc.patient }}{% if pname and pname != doc.patient %} - {{ pname }}{% endif %} ({{ (doc.patient_sex or pt.sex or "")[:1] }}){% if age %} / {{ age }}{% endif %}</b>
    {% if pt.mobile %}&nbsp;&nbsp;<b>Mob. No.:</b> {{ pt.mobile }}{% endif %}
  </div>
  <div>
    {% if v.weight %}Weight (Kg): {{ v.weight }}{% endif %}
    {% if v.height %}, Height (Cm): {{ v.height }}{% endif %}
    {% if v.bmi %}(B.M.I. = {{ v.bmi }}){% endif %}
    {% if v.bp_systolic and v.bp_diastolic %}, BP: {{ v.bp_systolic | int }}/{{ v.bp_diastolic | int }} mmHg{% endif %}
  </div>

  <!-- Complaints / Diagnosis -->
  <table class="box" style="margin-top:12px">
    <tr><th style="width:50%">Chief Complaints</th><th>Diagnosis</th></tr>
    <tr>
      <td>
        <ul>
          {% for s in doc.symptoms or [] %}<li>{{ s.complaint | upper }}</li>{% endfor %}
        </ul>
      </td>
      <td>
        <ul>
          {% for d in doc.diagnosis or [] %}<li>{{ d.diagnosis | upper }}</li>{% endfor %}
        </ul>
      </td>
    </tr>
  </table>
  <hr style="margin-top:0">

  <div style="font-size:16px; margin-top:14px">&#8478;</div>

  <!-- Medicines -->
  <table class="meds">
    <tr>
      <th style="width:42%">Medicine Name</th>
      <th style="width:30%">Dosage</th>
      <th>Duration</th>
    </tr>
    {% for d in doc.drug_prescription or [] %}
    <tr>
      <td>
        {{ loop.index }}) {{ (d.dosage_form or "") | upper }} {{ (d.drug_name or d.drug_code) | upper }}
        {% if d.strength %}<span class="sub">{{ d.strength }} {{ d.strength_time or "" }}</span>{% endif %}
      </td>
      <td>
        {{ d.dosage or "" }}
        {% if d.comment %}<br>({{ d.comment }}){% endif %}
      </td>
      <td>{{ d.period or "" }}</td>
    </tr>
    {% endfor %}
  </table>

  <!-- Lab tests / procedures (shown only when present) -->
  {% if doc.lab_test_prescription %}
  <div class="sec">Investigations:</div>
  <ul>
    {% for l in doc.lab_test_prescription %}<li>{{ l.lab_test_name or l.lab_test_code }}</li>{% endfor %}
  </ul>
  {% endif %}
  {% if doc.procedure_prescription %}
  <div class="sec">Procedures:</div>
  <ul>
    {% for p in doc.procedure_prescription %}<li>{{ p.procedure_name or p.procedure }}</li>{% endfor %}
  </ul>
  {% endif %}

  <!-- Bottom block: advice, follow-up, footer -->
  <div class="bottom">
  <div class="sec">Advice:</div>
  <ul>
    <li>TAKE BED REST</li>
    <li>DO NOT EAT OUTSIDE FOOD</li>
    <li>EAT EASY TO DIGEST FOOD LIKE BOILED RICE WITH DAAL</li>
    {% if doc.encounter_comment %}
      {# each line of the comments field becomes its own advice point #}
      {% set plain = frappe.utils.strip_html(doc.encounter_comment | replace("<br>", "\n") | replace("</p>", "\n") | replace("</div>", "\n")) %}
      {% for line in plain.split("\n") if line.strip() %}
        <li>{{ line.strip() | upper }}</li>
      {% endfor %}
    {% endif %}
  </ul>

  {% if doc.get("follow_up_date") %}
  <div class="sec">Follow Up: {{ frappe.utils.formatdate(doc.follow_up_date, "dd-MM-yyyy") }}</div>
  {% endif %}

  <div class="foot">Substitute with equivalent Generics as required.</div>
  </div>
</div>
